function sanitize(val) {
  if (val === null || val === undefined) return '';
  return String(val).replace(/'/g, "''").trim();
}
const b = items[0].json.body || items[0].json;

// Handle both: HA flat format (omschrijving1..3) and array format (regels)
let regels;
if (b.regels && Array.isArray(b.regels) && b.regels.length > 0) {
  regels = b.regels.map(r => ({
    omschrijving: sanitize(r.omschrijving),
    aantal: parseFloat(r.aantal) || 1,
    prijs: parseFloat(r.prijs) || 0,
    btw_tarief: parseFloat(r.btw_tarief) || 21
  }));
} else {
  // HA flat format: omschrijving1..3, aantal1..3, prijs1..3, btw1..3
  regels = [];
  for (let i = 1; i <= 3; i++) {
    const omschr = sanitize(b['omschrijving' + i] || '');
    const prijs = parseFloat(b['prijs' + i]) || 0;
    if (omschr && prijs > 0) {
      regels.push({
        omschrijving: omschr,
        aantal: parseFloat(b['aantal' + i]) || 1,
        prijs: prijs,
        btw_tarief: parseFloat(b['btw' + i]) || 21
      });
    }
  }
}

return [{ json: {
  klant: sanitize(b.klant),
  project: sanitize(b.project || ''),
  grootboek: sanitize(b.grootboek || ''),
  regels: regels,
  notities: sanitize(b.notities || '')
}}];

