const companyEmail = $('MySQL: Bedrijfsinstellingen ophalen').first().json.value || '';
const year = new Date().getFullYear();
const num = String(counter).padStart(4, '0');
const invoice_number = `F${year}-${num}`;
return [{ json: {
  body,
  customer,
  invoice_number,
  company_email: companyEmail
}}];

